def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    def longest_straight_run(cells):
        rows, cols = {}, {}
        for r, c in cells:
            rows.setdefault(r, []).append(c)
            cols.setdefault(c, []).append(r)
        best = 0
        for groups in (rows.values(), cols.values()):
            for vals in groups:
                vals.sort()
                run, prev = 0, None
                for v in vals:
                    run = run + 1 if prev is not None and v == prev + 1 else 1
                    prev = v
                    best = max(best, run)
        return best

    marker = max(comps, key=lambda comp: longest_straight_run(comp[1]))
    marker_color, marker_cells = marker
    targets = [comp for comp in comps if comp is not marker]
    if not targets:
        return [row[:] for row in grid]

    target = min(
        targets,
        key=lambda comp: min(abs(r-y) + abs(c-x)
                             for r, c in marker_cells for y, x in comp[1])
    )
    out = [row[:] for row in grid]
    for r, c in target[1]:
        out[r][c] = marker_color
    return out
